// Analyze recent activity and decide if proactive action is needed
// Returns decision and optional task to execute

const analyzeActivity = () => {
  const recentMemories = $('Check Recent Activity').all();
  const now = new Date();
  const hour = now.getHours();

  // Don't disturb during sleep hours (11 PM - 7 AM)
  if (hour >= 23 || hour < 7) {
    return {
      action: 'none',
      reason: 'quiet_hours',
      message: null
    };
  }

  // Check if there's been any activity today
  if (recentMemories.length === 0) {
    return {
      action: 'none',
      reason: 'no_activity',
      message: null
    };
  }

  // Get the most recent activity
  const lastActivity = recentMemories[0];
  const lastActivityTime = new Date(lastActivity.created_at);
  const hoursSinceActivity = (now - lastActivityTime) / (1000 * 60 * 60);

  // If it's been more than 8 hours since last activity, maybe check in
  if (hoursSinceActivity > 8) {
    return {
      action: 'checkin',
      reason: 'long_silence',
      message: 'Hey! I noticed it\'s been a while since we last talked. Just checking in - anything I can help with today? 😊'
    };
  }

  // Look for patterns that might need attention
  const todaysActivities = recentMemories.map(m => m.content.toLowerCase());

  // Check for mentions of reminders or tasks
  const hasReminders = todaysActivities.some(activity => 
    activity.includes('remind') || 
    activity.includes('task') ||
    activity.includes('todo') ||
    activity.includes('later')
  );

  if (hasReminders && hour >= 9 && hour <= 17) {
    return {
      action: 'reminder_check',
      reason: 'pending_tasks',
      message: 'I noticed you mentioned some tasks or reminders earlier. Would you like me to help you organize or check on anything?'
    };
  }

  // Check for error patterns or frustrations
  const hasErrors = todaysActivities.some(activity =>
    activity.includes('error') ||
    activity.includes('problem') ||
    activity.includes('issue') ||
    activity.includes('not working')
  );

  if (hasErrors) {
    return {
      action: 'help_offer',
      reason: 'detected_issues',
      message: 'I saw you were dealing with some issues earlier. Need any help troubleshooting or want to talk through anything?'
    };
  }

  // Default: no action needed
  return {
    action: 'none',
    reason: 'all_good',
    message: null
  };
};

return analyzeActivity();
